import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64

.visible .entry conv2d_kernel(
    .param .u64 in_ptr,
    .param .u64 w_ptr,
    .param .u64 b_ptr,
    .param .u64 out_ptr,
    .param .u32 total
)
{
    .reg .pred %p<8>;
    .reg .b32 %r<64>;
    .reg .b64 %rd<16>;
    .reg .f32 %f<8>;

    mov.u32 %r0, %ctaid.x;
    mov.u32 %r1, %ntid.x;
    mov.u32 %r2, %tid.x;
    mul.lo.u32 %r3, %r0, %r1;
    add.u32 %r3, %r3, %r2;
    mov.u32 %r4, %nctaid.x;
    mul.lo.u32 %r5, %r4, %r1;

    ld.param.u64 %rd1, [in_ptr];
    ld.param.u64 %rd2, [w_ptr];
    ld.param.u64 %rd3, [b_ptr];
    ld.param.u64 %rd4, [out_ptr];
    ld.param.u32 %r6, [total];

LOOP:
    setp.ge.u32 %p1, %r3, %r6;
    @%p1 bra DONE;

    rem.u32 %r7, %r3, 55;
    div.u32 %r8, %r3, 55;
    rem.u32 %r9, %r8, 55;
    div.u32 %r10, %r8, 55;
    rem.u32 %r11, %r10, 96;
    div.u32 %r12, %r10, 96;

    mov.f32 %f0, 0f00000000;

    mov.u32 %r13, 0;
C_LOOP:
    setp.ge.u32 %p2, %r13, 3;
    @%p2 bra C_END;

    mov.u32 %r14, 0;
KH_LOOP:
    setp.ge.u32 %p3, %r14, 11;
    @%p3 bra KH_END;

    mul.lo.u32 %r15, %r9, 4;
    add.u32 %r15, %r15, %r14;
    sub.s32 %r15, %r15, 2;
    setp.lt.s32 %p4, %r15, 0;
    setp.ge.s32 %p5, %r15, 224;
    or.pred %p6, %p4, %p5;
    @%p6 bra KH_NEXT;

    mov.u32 %r16, 0;
KW_LOOP:
    setp.ge.u32 %p7, %r16, 11;
    @%p7 bra KW_END;

    mul.lo.u32 %r17, %r7, 4;
    add.u32 %r17, %r17, %r16;
    sub.s32 %r17, %r17, 2;
    setp.lt.s32 %p4, %r17, 0;
    setp.ge.s32 %p5, %r17, 224;
    or.pred %p6, %p4, %p5;
    @%p6 bra KW_NEXT;

    mul.lo.u32 %r18, %r12, 3;
    add.u32 %r18, %r18, %r13;
    mul.lo.u32 %r18, %r18, 224;
    add.u32 %r18, %r18, %r15;
    mul.lo.u32 %r18, %r18, 224;
    add.u32 %r18, %r18, %r17;
    mul.wide.u32 %rd5, %r18, 4;
    add.u64 %rd6, %rd1, %rd5;
    ld.global.f32 %f1, [%rd6];

    mul.lo.u32 %r19, %r11, 3;
    add.u32 %r19, %r19, %r13;
    mul.lo.u32 %r19, %r19, 11;
    add.u32 %r19, %r19, %r14;
    mul.lo.u32 %r19, %r19, 11;
    add.u32 %r19, %r19, %r16;
    mul.wide.u32 %rd7, %r19, 4;
    add.u64 %rd8, %rd2, %rd7;
    ld.global.f32 %f2, [%rd8];

    fma.rn.f32 %f0, %f1, %f2, %f0;

KW_NEXT:
    add.u32 %r16, %r16, 1;
    bra KW_LOOP;
KW_END:

KH_NEXT:
    add.u32 %r14, %r14, 1;
    bra KH_LOOP;
KH_END:

    add.u32 %r13, %r13, 1;
    bra C_LOOP;
C_END:

    mul.wide.u32 %rd9, %r11, 4;
    add.u64 %rd10, %rd3, %rd9;
    ld.global.f32 %f3, [%rd10];
    add.f32 %f0, %f0, %f3;

    mul.wide.u32 %rd11, %r3, 4;
    add.u64 %rd12, %rd4, %rd11;
    st.global.f32 [%rd12], %f0;

    add.u32 %r3, %r3, %r5;
    bra LOOP;
DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("conv2d_kernel")

class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super().__init__()
        self.conv1 = nn.Conv2d(in_channels=3, out_channels=96, kernel_size=11, stride=4, padding=2)

    def forward(self, x):
        x = x.contiguous()
        weight = self.conv1.weight.contiguous()
        bias = self.conv1.bias.contiguous()

        n, c, h, w = x.shape
        kh, kw = self.conv1.kernel_size
        sh, sw = self.conv1.stride
        ph, pw = self.conv1.padding
        oh = (h + 2 * ph - kh) // sh + 1
        ow = (w + 2 * pw - kw) // sw + 1

        out = torch.empty((n, 96, oh, ow), device=x.device, dtype=x.dtype)
        total = out.numel()

        module = _get_ptx_module()
        module.launch(
            "conv2d_kernel",
            grid=((total + 255) // 256, 1, 1),
            block=(256, 1, 1),
            arguments=[x, weight, bias, out, u32(total)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return out

